#include "fio.h"

static int initialized = 0;

const char *const fakeargv[] = {(char *) "fuzz",
        (char *) "--output", (char *) "/dev/null",
        (char *) "--parse-only",
        0};

int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size)
{
        char *fuzzedini;

        if (size < 2)
                return 0;

        if (initialized == 0) {
                if (fio_init_options()) {
                        printf("Failed fio_init_options\n");
                        return 1;
                }

                parse_cmd_line(4, (char **) fakeargv, 0);
                sinit();

                initialized = 1;
        }
        fuzzedini = malloc(size);
        if (!fuzzedini) {
                printf("Failed malloc\n");
                return 1;
        }
        /* final character is type for parse_jobs_ini */
        memcpy(fuzzedini, data, size - 1);
        /* ensures final 0 */
        fuzzedini[size - 1] = 0;

        parse_jobs_ini(fuzzedini, 1, 0, data[size - 1]);
        free(fuzzedini);
        return 0;
}

static int __parse_jobs_ini(struct thread_data *td,
                char *file, int is_buf, int stonewall_flag, int type,
                int nested, char *name, char ***popts, int *aopts, int *nopts)
{
        bool global = false;
        bool stdin_occupied = false;
        char *string;
        FILE *f;
        char *p;
        int ret = 0, stonewall;
        int first_sect = 1;
        int skip_fgets = 0;
        int inside_skip = 0;
        char **opts;
        int i, alloc_opts, num_opts;

        dprint(FD_PARSE, "Parsing ini file %s\n", file);
        assert(td || !nested);

        if (is_buf)
                f = NULL;
        else {
                if (!strcmp(file, "-")) {
                        f = stdin;
                        stdin_occupied = true;
                } else
                        f = fopen(file, "r");

                if (!f) {
                        int __err = errno;

                        log_err("fio: unable to open '%s' job file\n", file);
                        if (td)
                                td_verror(td, __err, "job file open");
                        return 1;
                }
        }

        string = malloc(OPT_LEN_MAX);

        /*
         * it's really 256 + small bit, 280 should suffice
         */
        if (!nested) {
                name = malloc(280);
                memset(name, 0, 280);
        }

        opts = NULL;
        if (nested && popts) {
                opts = *popts;
                alloc_opts = *aopts;
                num_opts = *nopts;
        }

        if (!opts) {
                alloc_opts = 8;
                opts = malloc(sizeof(char *) * alloc_opts);
                num_opts = 0;
        }

        stonewall = stonewall_flag;
        do {
                /*
                 * if skip_fgets is set, we already have loaded a line we
                 * haven't handled.
                 */
                if (!skip_fgets) {
                        if (is_buf)
                                p = strsep(&file, "\n");
                        else
                                p = fgets(string, OPT_LEN_MAX, f);
                        if (!p)
                                break;
                }

                skip_fgets = 0;
                strip_blank_front(&p);
                strip_blank_end(p);

                dprint(FD_PARSE, "%s\n", p);
                if (is_empty_or_comment(p))
                        continue;

                if (!nested) {
                        if (sscanf(p, "[%255[^\n]]", name) != 1) {
                                if (inside_skip)
                                        continue;

                                log_err("fio: option <%s> outside of "
                                        "[] job section\n", p);
                                ret = 1;
                                break;
                        }

                        name[strlen(name) - 1] = '\0';

                        if (skip_this_section(name)) {
                                inside_skip = 1;
                                continue;
                        } else
                                inside_skip = 0;

                        dprint(FD_PARSE, "Parsing section [%s]\n", name);

                        global = !strncmp(name, "global", 6);

                        if (dump_cmdline) {
                                if (first_sect)
                                        log_info("fio ");
                                if (!global)
                                        log_info("--name=%s ", name);
                                first_sect = 0;
                        }

                        td = get_new_job(global, &def_thread, false, name);
                        if (!td) {
                                ret = 1;
                                break;
                        }

                        /*
                         * Separate multiple job files by a stonewall
                         */
                        if (!global && stonewall) {
                                td->o.stonewall = stonewall;
                                stonewall = 0;
                        }

                        num_opts = 0;
                        memset(opts, 0, alloc_opts * sizeof(char *));
                }
                else
                        skip_fgets = 1;

                while (1) {
                        if (!skip_fgets) {
                                if (is_buf)
                                        p = strsep(&file, "\n");
                                else
                                        p = fgets(string, OPT_LEN_MAX, f);
                                if (!p)
                                        break;
                                dprint(FD_PARSE, "%s", p);
                        }
                        else
                                skip_fgets = 0;

                        if (is_empty_or_comment(p))
                                continue;

                        strip_blank_front(&p);

                        /*
                         * new section, break out and make sure we don't
                         * fgets() a new line at the top.
                         */
                        if (p[0] == '[') {
                                if (nested) {
                                        log_err("No new sections in included files\n");
                                        ret = 1;
                                        goto out;
                                }

                                skip_fgets = 1;
                                break;
                        }

                        strip_blank_end(p);

                        if (!strncmp(p, "include", strlen("include"))) {
                                char *filename = p + strlen("include") + 1,
                                        *ts, *full_fn = NULL;

                                /*
                                 * Allow for the include filename
                                 * specification to be relative.
                                 */
                                if (access(filename, F_OK) &&
                                    (ts = strrchr(file, '/'))) {
                                        if (asprintf(&full_fn, "%.*s%s",
                                                 (int)(ts - file + 1), file,
                                                 filename) < 0) {
                                                ret = ENOMEM;
                                                break;
                                        }
                                        filename = full_fn;
                                }

                                ret = __parse_jobs_ini(td, filename, is_buf,
                                                       stonewall_flag, type, 1,
                                                       name, &opts,
                                                       &alloc_opts, &num_opts);

                                if (ret) {
                                        log_err("Error %d while parsing "
                                                "include file %s\n",
                                                ret, filename);
                                }

                                if (full_fn)
                                        free(full_fn);

                                if (ret)
                                        break;

                                continue;
                        }

                        if (num_opts == alloc_opts) {
                                alloc_opts <<= 1;
                                opts = realloc(opts,
                                                alloc_opts * sizeof(char *));
                        }

                        opts[num_opts] = strdup(p);
                        num_opts++;
                }

                if (nested) {
                        *popts = opts;
                        *aopts = alloc_opts;
                        *nopts = num_opts;
                        goto out;
                }

                ret = fio_options_parse(td, opts, num_opts);

                if (!ret && td->o.read_iolog_file != NULL) {
                        char *fname = get_name_by_idx(td->o.read_iolog_file,
                                                      td->subjob_number);
                        if (!strcmp(fname, "-")) {
                                if (stdin_occupied) {
                                        log_err("fio: only one user (read_iolog_file/job "
                                                "file) of stdin is permitted at once but "
                                                "more than one was found.\n");
                                        ret = 1;
                                }
                                stdin_occupied = true;
                        }
                }
                if (!ret) {
                        if (dump_cmdline)
                                dump_opt_list(td);

                        ret = add_job(td, name, 0, 0, type);
                } else {
                        log_err("fio: job %s dropped\n", name);
                        put_job(td);
                }

                for (i = 0; i < num_opts; i++)
                        free(opts[i]);
                num_opts = 0;
        } while (!ret);

        if (dump_cmdline)
                log_info("\n");

        i = 0;
        while (i < nr_job_sections) {
                free(job_sections[i]);
                i++;
        }

        free(opts);
out:
        free(string);
        if (!nested)
                free(name);
        if (!is_buf && f != stdin)
                fclose(f);
        return ret;
}

int parse_jobs_ini(char *file, int is_buf, int stonewall_flag, int type)
{
        return __parse_jobs_ini(NULL, file, is_buf, stonewall_flag, type,
                        0, NULL, NULL, NULL, NULL);
}

